import (
    "fmt"
    "time"
)

func printNumbers(prefix string) {
    for i := 1; i <= 3; i++ {
        time.Sleep(100 * time.Millisecond)
        fmt.Printf("%s: %d
", prefix, i)
    }
}

func main() {
    // Run as goroutine
    go printNumbers("Async")

    // Run normally (blocks)
    printNumbers("Sync")

